import sys

data = sys.stdin.read().split()
n = int(data[0])
edge = [int(x) for x in data[1:1 + n]]
c1, c2 = int(data[1 + n]), int(data[2 + n])

def steps(s, v):
    x = s
    for t in range(n + 1):
        if x == v:
            return t
        if x == -1:
            return -1
        x = edge[x]
    return -1

best_v, best_cost = -1, None
for v in range(n):
    a, b = steps(c1, v), steps(c2, v)
    if a >= 0 and b >= 0:
        if best_cost is None or a + b < best_cost:
            best_cost = a + b
            best_v = v
print(best_v)

